import React, { useState, useRef } from "react";
import "./App.css";

function App() {
  const [disease, setDisease] = useState("");
  const [intent, setIntent] = useState("");
  const [location, setLocation] = useState("");
  const [mode, setMode] = useState("fast");

  const [summary, setSummary] = useState("");
  const [publications, setPublications] = useState([]);
  const [trials, setTrials] = useState([]);
  const [loading, setLoading] = useState(false);

  const summaryRef = useRef(null);

  // 🚀 SEARCH
  const handleSearch = async () => {
    if (!intent.trim() && !disease.trim()) {
      alert("Enter disease or question");
      return;
    }

    setLoading(true);

    // ⚡ FAST MODE
    if (mode === "fast") {
      setSummary(`Condition Overview:
${disease || "General medical condition"}

Key Insights:
• Early diagnosis is important  
• Treatment depends on severity  
• Lifestyle + medication helps  

Recommendation:
Consult a healthcare professional`);

      setPublications([]);
      setTrials([]);
      setLoading(false);
      return;
    }

    // 🔬 DEEP MODE (with timeout)
    try {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 8000);

      const res = await fetch("http://localhost:8000/analyze", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          disease,
          intent,
          location,
        }),
        signal: controller.signal,
      });

      clearTimeout(timeout);

      const data = await res.json();

      setSummary(data.insights || "");
      setPublications(data.publications || []);
      setTrials(data.clinical_trials || []);

      setTimeout(() => {
        summaryRef.current?.scrollIntoView({ behavior: "smooth" });
      }, 200);

    } catch (err) {
      console.error(err);
      setSummary("⚠️ Server slow. Use Fast Mode.");
    }

    setLoading(false);
  };

  const handleKeyPress = (e) => {
    if (e.key === "Enter") handleSearch();
  };

  return (
    <div className="app">

      {/* 🔵 LEFT SIDEBAR */}
      <div className="sidebar">
        <h1>Curalink X</h1>
        <p>AI Medical Research Copilot</p>

        <input
          placeholder="e.g., Parkinson's disease"
          value={disease}
          onChange={(e) => setDisease(e.target.value)}
        />

        <div className="filters">
          <label><input type="checkbox" defaultChecked /> Publications</label>
          <label><input type="checkbox" defaultChecked /> Clinical trials</label>
          <label><input type="checkbox" defaultChecked /> Risk analysis</label>
        </div>

        <div className="mode-toggle">
          <button
            className={mode === "fast" ? "active" : ""}
            onClick={() => setMode("fast")}
          >
            ⚡ Fast
          </button>

          <button
            className={mode === "deep" ? "active" : ""}
            onClick={() => setMode("deep")}
          >
            🔬 Deep
          </button>
        </div>

        <div className="stats">
          <p>Research papers: {publications.length}</p>
          <p>Clinical trials: {trials.length}</p>
          <p>Risk confidence: 0%</p>
          <p>Pipeline time: ~250 ms</p>
        </div>
      </div>

      {/* 🟣 CENTER */}
      <div className="main">
        <h1>OpenAI reasoning copilot</h1>

        <textarea
          placeholder="Ask your medical research question..."
          value={intent}
          onChange={(e) => setIntent(e.target.value)}
          onKeyDown={handleKeyPress}
        />

        <button onClick={handleSearch}>
          {loading ? "⏳ Thinking..." : "Send message"}
        </button>

        <div className="metadata">
          <input
            placeholder="Location"
            value={location}
            onChange={(e) => setLocation(e.target.value)}
          />
        </div>

        {summary && (
          <div className="summary" ref={summaryRef}>
            <h3>AI Summary</h3>
            <div className="summary-content">
              {summary.split("\n").map((line, i) => (
                <p key={i}>{line}</p>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* 🟢 RIGHT PANEL */}
      <div className="right">

        <div className="card">
          <h3>Dynamic Insights</h3>
          <p>Live synthesis</p>
        </div>

        <div className="card">
          <h3>Research papers</h3>
          {publications.length === 0 ? (
            <p>No publication cards available yet</p>
          ) : (
            publications.map((p, i) => (
              <div key={i} className="item">
                <h4>{p.title}</h4>
                <a href={p.link} target="_blank" rel="noreferrer">
                  View Paper
                </a>
              </div>
            ))
          )}
        </div>

        <div className="card">
          <h3>Clinical trials</h3>
          {trials.length === 0 ? (
            <p>No clinical trials matched the current filters.</p>
          ) : (
            trials.map((t, i) => (
              <div key={i} className="item">
                <h4>{t.title}</h4>
                <p>Status: {t.status}</p>
              </div>
            ))
          )}
        </div>

        <div className="card">
          <h3>Risk analysis</h3>
          <p>Risk analysis will appear after the first run.</p>
        </div>

        <div className="card">
          <h3>What-if Analysis</h3>
          <input placeholder="e.g., Vitamin D" />
          <button>Simulate scenario</button>
        </div>

      </div>
    </div>
  );
}

export default App;
